<template>
  <div class="page-shell"><header class="page-header"><div><el-tag>第 4 步 / 4</el-tag><h1>AI 个性化面试方案</h1><p>智能体已根据能力缺口生成多轮问询计划</p></div><el-button @click="router.push('/job-match')">上一步</el-button></header>
    <el-steps :active="3" finish-status="success" class="flow"><el-step title="简历分析"/><el-step title="岗位建模"/><el-step title="人岗匹配"/><el-step title="评估方案"/></el-steps>
    <el-row :gutter="20"><el-col :xs="24" :lg="16"><el-card shadow="never" v-loading="loading"><template #header><div class="card-title"><strong>评估规划</strong><el-tag type="success">AI 已生成</el-tag></div></template><el-descriptions :column="3" border><el-descriptions-item label="评估目标">{{ plan.objective }}</el-descriptions-item><el-descriptions-item label="目标岗位">{{ session.jobProfile.name }}</el-descriptions-item><el-descriptions-item label="预计时间">{{ plan.estimatedMinutes }} 分钟</el-descriptions-item><el-descriptions-item label="面试策略" :span="3"><el-tag v-for="item in plan.strategies" :key="item" class="tag">{{ item }}</el-tag></el-descriptions-item></el-descriptions>
        <h3>分阶段问询计划</h3><el-steps direction="vertical" :active="0" process-status="process"><el-step v-for="stage in plan.stages" :key="stage.id" :title="stage.name" :description="`${stage.questionCount} 个核心问题，并根据证据强度动态追问`"/></el-steps>
        <h3>AI 将如何追问</h3><el-row :gutter="12"><el-col v-for="(item,index) in plan.followUpExamples" :key="item" :span="8"><el-card shadow="hover" class="question-card"><span>追问 {{ index+1 }}</span><p>{{ item }}</p></el-card></el-col></el-row>
      </el-card></el-col>
      <el-col :xs="24" :lg="8"><el-card shadow="never"><template #header><strong>重点考察能力</strong></template><div v-for="item in session.competencyModel" :key="item.id" class="focus-row"><div><strong>{{ item.name }}</strong><small>岗位权重 {{ item.weight }}%</small></div><el-progress type="circle" :percentage="item.targetScore" :width="58" :stroke-width="7"/></div></el-card><el-card shadow="never" class="strategy"><template #header><strong>智能体决策原则</strong></template><p>{{ plan.strategy }}</p><p>当证据不足、回答模糊或与简历冲突时，AI 会自动进行澄清或反证追问。</p></el-card></el-col></el-row>
    <div class="actions"><el-button type="primary" size="large" :loading="starting" @click="start">开始 AI 面试</el-button><p>创建评估会话后进入现有面试页面，聊天核心保持不变。</p></div>
  </div>
</template>
<script setup>
import { computed,onMounted,ref } from "vue";import { useRouter } from "vue-router";import { ElMessage } from "element-plus";import { createAssessment,generateInterviewPlan } from "@/api/assessment";import { useAssessmentStore } from "@/store/assessment";import { useInterviewStore } from "@/store/interview";
const router=useRouter();const store=useAssessmentStore();const legacyStore=useInterviewStore();const loading=ref(false);const starting=ref(false);const session=computed(()=>store.session);const plan=computed(()=>session.value.interviewPlan||{});
onMounted(async()=>{if(!session.value.matchResult){ElMessage.warning("请先完成人岗匹配");router.replace('/job-match');return}if(!plan.value.objective){loading.value=true;store.setInterviewPlan(await generateInterviewPlan({matchResult:session.value.matchResult}));loading.value=false}});
const start=async()=>{starting.value=true;try{const created=await createAssessment(session.value);store.createAssessment(created);legacyStore.setInterviewData({chatId:created.assessmentId,jobRole:created.jobProfile.name,resumeFile:null});ElMessage.success(`评估任务 ${created.assessmentId} 创建成功`);router.push('/interview')}finally{starting.value=false}};
</script>
<style scoped>.page-shell{min-height:100vh;padding:32px 5%;background:#f5f7fa}.page-header,.card-title{display:flex;justify-content:space-between;align-items:center}.page-header h1{margin:10px 0 4px}.page-header p,.actions p{color:#909399}.flow{margin:28px 0 34px}.tag{margin:4px}h3{margin:24px 0 16px}.question-card{height:130px}.question-card span{color:#409eff;font-size:13px}.question-card p{line-height:1.6}.focus-row{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #ebeef5}.focus-row small{display:block;margin-top:7px;color:#909399}.strategy{margin-top:20px;line-height:1.7;color:#606266}.actions{text-align:center;margin-top:28px}@media(max-width:992px){.el-col{margin-bottom:16px}}</style>
